--
-- Table structure for table `atendimento_eventos`
--

DROP TABLE IF EXISTS `atendimento_eventos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `atendimento_eventos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `incidente_id` bigint(20) unsigned NOT NULL,
  `atendimento_tipo` enum('especialista','guincho') NOT NULL,
  `atendimento_id` bigint(20) unsigned NOT NULL,
  `evento` varchar(50) NOT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `accuracy_m` decimal(8,2) DEFAULT NULL,
  `metadata_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata_json`)),
  `criado_em` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_atendimento_evento` (`atendimento_tipo`,`atendimento_id`,`criado_em`),
  KEY `fk_evento_incidente` (`incidente_id`),
  CONSTRAINT `fk_evento_incidente` FOREIGN KEY (`incidente_id`) REFERENCES `incidentes` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

