DROP TABLE IF EXISTS `marketing_campaign_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `marketing_campaign_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `campaign_id` int(11) NOT NULL,
  `event_type` varchar(40) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `partner_prospect_id` bigint(20) unsigned DEFAULT NULL,
  `pricing_zone_id` int(11) DEFAULT NULL,
  `metadata_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata_json`)),
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_campaign_events_campaign_date` (`campaign_id`,`created_at`),
  KEY `idx_campaign_events_type_date` (`event_type`,`created_at`),
  CONSTRAINT `fk_campaign_events_campaign` FOREIGN KEY (`campaign_id`) REFERENCES `marketing_campaigns` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

