  `pagamento_id` bigint(20) unsigned NOT NULL,
  `gateway` varchar(30) NOT NULL DEFAULT 'mercadopago',
  `status_liquidacao_gateway` varchar(50) DEFAULT NULL,
  `valor_bruto` decimal(10,2) DEFAULT NULL,
  `valor_liquido` decimal(10,2) DEFAULT NULL,
  `taxas_gateway` decimal(10,2) DEFAULT NULL,
  `data_prevista_liquidacao` date DEFAULT NULL,
  `data_liquidacao_confirmada` date DEFAULT NULL,
  `payload_resumido` text DEFAULT NULL,
  `hash_evento` varchar(64) DEFAULT NULL COMMENT 'Idempot??ncia de webhook',
  `criado_em` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_pagamento_id` (`pagamento_id`),
  KEY `idx_hash_evento` (`hash_evento`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
