--
-- Table structure for table `pagamentos`
--

DROP TABLE IF EXISTS `pagamentos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pagamentos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pedido_id` int(11) NOT NULL,
  `endereco_id` int(11) DEFAULT NULL,
  `metodo` enum('mercadopago','pagseguro','pix','dinheiro') NOT NULL DEFAULT 'mercadopago',
  `id_externo` varchar(255) DEFAULT NULL COMMENT 'ID da transa????o',
  `status_gateway` varchar(50) DEFAULT NULL COMMENT 'Status do gateway',
  `payload_webhook` text DEFAULT NULL COMMENT 'JSON do webhook',
  `valor_total` decimal(10,2) NOT NULL,
  `valor_guincho` decimal(10,2) NOT NULL,
  `valor_plataforma` decimal(10,2) NOT NULL,
  `comissao_plataforma` decimal(10,2) DEFAULT NULL,
  `status` enum('pendente','aprovado','recusado','estornado','estornando') NOT NULL DEFAULT 'pendente',
  `codigo_transacao` varchar(100) DEFAULT NULL,
  `pago_guincho` tinyint(1) DEFAULT 0,
  `data_pagamento_guincho` datetime DEFAULT NULL,
  `id_transacao_pix` varchar(100) DEFAULT NULL,
  `status_pix` enum('pendente','processando','concluido','falha','falha_permanente') NOT NULL DEFAULT 'pendente',
  `status_carteira` enum('em_compensacao','liberado','reservado_saque','pago','bloqueado') NOT NULL DEFAULT 'em_compensacao',
  `pix_tentativas` int(11) NOT NULL DEFAULT 0,
  `proximo_repasse_em` datetime DEFAULT NULL,
  `webhook_payload` text DEFAULT NULL,
  `data_pagamento` datetime DEFAULT NULL,
  `dados_webhook` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`dados_webhook`)),
  `criado_em` datetime DEFAULT current_timestamp(),
  `atualizado_em` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `tentativa` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pedido_id` (`pedido_id`),
  UNIQUE KEY `uk_pagamentos_pedido_id` (`pedido_id`),
  KEY `idx_pedido_id` (`pedido_id`),
  KEY `idx_status` (`status`),
  KEY `idx_codigo_transacao` (`codigo_transacao`),
  KEY `idx_pagamentos_id_externo` (`id_externo`),
  KEY `idx_pagamentos_status` (`status`),
  KEY `idx_pagamentos_pix_retry` (`status_pix`,`pix_tentativas`,`proximo_repasse_em`),
  KEY `idx_status_carteira` (`status_carteira`),
  KEY `idx_pagamentos_endereco` (`endereco_id`),
  CONSTRAINT `fk_pagamentos_pedido` FOREIGN KEY (`pedido_id`) REFERENCES `pedidos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pagamentos_ibfk_1` FOREIGN KEY (`pedido_id`) REFERENCES `pedidos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
