DROP TABLE IF EXISTS `pedido_evidencias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pedido_evidencias` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `pedido_id` int(11) NOT NULL,
  `guincho_id` int(11) NOT NULL,
  `tipo` enum('coleta','entrega','CHECKIN_OFICINA') NOT NULL,
  `status` enum('pending','accepted','rejected') NOT NULL DEFAULT 'accepted',
  `nonce_token` varchar(255) NOT NULL,
  `nonce_expires_at` datetime NOT NULL,
  `point_id` bigint(20) unsigned NOT NULL,
  `latitude` decimal(10,8) NOT NULL,
  `longitude` decimal(11,8) NOT NULL,
  `accuracy_m` decimal(10,2) DEFAULT NULL,
  `device_timestamp` bigint(20) DEFAULT NULL,
  `server_timestamp` datetime NOT NULL DEFAULT current_timestamp(),
  `original_name` varchar(255) NOT NULL,
  `stored_name` varchar(255) NOT NULL,
  `mime_type` varchar(120) NOT NULL,
  `size_bytes` bigint(20) unsigned NOT NULL,
  `sha256` char(64) NOT NULL,
  `metadata_json` longtext DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_nonce_token` (`nonce_token`),
  UNIQUE KEY `uk_pedido_tipo_sha256` (`pedido_id`,`tipo`,`sha256`),
  KEY `idx_pedido_tipo` (`pedido_id`,`tipo`,`status`),
  KEY `idx_point_id` (`point_id`),
  KEY `fk_evd_guincho` (`guincho_id`),
  CONSTRAINT `fk_evd_guincho` FOREIGN KEY (`guincho_id`) REFERENCES `guinchos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_evd_pedido` FOREIGN KEY (`pedido_id`) REFERENCES `pedidos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_evd_point` FOREIGN KEY (`point_id`) REFERENCES `pedido_localizacoes` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
