  `attendance_mode` enum('TOWING','ON_SITE','HYBRID') NOT NULL DEFAULT 'TOWING',
  `tipo_problema` enum('mecanico','eletrico','pneu','bateria','combustivel','acidente','outro') NOT NULL,
  `descricao_problema` text DEFAULT NULL,
  `lat_origem` decimal(10,8) NOT NULL,
  `lng_origem` decimal(11,8) NOT NULL,
  `endereco_origem` text NOT NULL,
  `lat_destino` decimal(10,8) DEFAULT NULL,
  `lng_destino` decimal(11,8) DEFAULT NULL,
  `local_resgate_lat` decimal(10,8) DEFAULT NULL,
  `local_resgate_lng` decimal(11,8) DEFAULT NULL,
  `endereco_destino` text NOT NULL,
  `distancia_km` decimal(8,2) NOT NULL,
  `distancia_guincho_origem_km` decimal(6,2) DEFAULT NULL,
  `distancia_guincho_percorrida` decimal(6,2) DEFAULT NULL,
  `custo_estimado` decimal(10,2) NOT NULL,
  `custo_assistencia` decimal(10,2) DEFAULT NULL,
  `custo_reboque` decimal(10,2) DEFAULT NULL,
  `orcamento_informado_at` datetime DEFAULT NULL,
