  `cliente_decisao_reboque` varchar(20) DEFAULT NULL,
  `decisoes_socorro_at` datetime DEFAULT NULL,
  `custo_final` decimal(10,2) DEFAULT NULL,
  `valor_estimado` decimal(10,2) NOT NULL,
  `valor_final` decimal(10,2) DEFAULT NULL,
  `status` enum('aguardando_pagamento','aguardando_guincho','aguardando_oficina','a_caminho','no_local','em_reboque','concluido','cancelado','diagnostico_iniciado','diagnostico_concluido','autorizacao_servico_pendente','em_execucao_servico','teste_final','conversao_reboque_pendente','conversao_aprovada_cliente','preparacao_veiculo','oficina_aceitou','oficina_a_caminho','orcamento_enviado','orcamento_aprovado') NOT NULL DEFAULT 'aguardando_pagamento',
  `modalidade_socorro` varchar(30) NOT NULL DEFAULT 'REBOQUE_TRADICIONAL',
  `concluido_manualmente` tinyint(1) NOT NULL DEFAULT 0,
  `revisao_manual_status` enum('pendente','confirmada','rejeitada') DEFAULT NULL,
  `concluido_manual_admin_id` int(11) DEFAULT NULL,
  `concluido_manual_justificativa` varchar(1000) DEFAULT NULL,
  `concluido_manual_em` datetime DEFAULT NULL,
  `revisao_manual_admin_id` int(11) DEFAULT NULL,
  `revisao_manual_em` datetime DEFAULT NULL,
  `revisao_manual_nota` varchar(500) DEFAULT NULL,
  `cancelado_por` enum('cliente','guincho','admin','sistema') DEFAULT NULL,
  `motivo_cancelamento` varchar(255) DEFAULT NULL,
  `taxa_cancelamento` decimal(10,2) NOT NULL DEFAULT 0.00,
  `cancelado_em` datetime DEFAULT NULL,
  `foto_plataforma` varchar(255) DEFAULT NULL,
  `foto_destino` varchar(255) DEFAULT NULL,
  `raio_atual_km` int(11) DEFAULT 10,
  `score_minimo_atual` decimal(5,4) DEFAULT 0.5000,
  `expiracao_aceite` datetime DEFAULT NULL,
  `raio_busca_km` int(11) DEFAULT 10,
  `score_minimo` decimal(5,4) DEFAULT 0.5000,
  `expira_em` datetime DEFAULT NULL,
  `criado_em` datetime DEFAULT current_timestamp(),
  `atualizado_em` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `utm_source` varchar(120) DEFAULT NULL,
  `utm_medium` varchar(120) DEFAULT NULL,
  `utm_campaign` varchar(180) DEFAULT NULL,
  `utm_content` varchar(180) DEFAULT NULL,
  `utm_term` varchar(180) DEFAULT NULL,
  `canal_aquisicao` varchar(40) NOT NULL DEFAULT 'organico',
  `referrer_url` varchar(1000) DEFAULT NULL,
  `landing_page` varchar(1000) DEFAULT NULL,
  `cidade_id` bigint(20) unsigned DEFAULT NULL,
  `observacao_interna` varchar(1000) DEFAULT NULL,
  `pricing_zone_id` int(11) DEFAULT NULL,
  `veiculo_esta_batido` tinyint(1) DEFAULT NULL,
  `rodas_travadas` tinyint(1) DEFAULT NULL,
  `local_dificil_acesso` tinyint(1) DEFAULT NULL,
  `em_garagem_subsolo` tinyint(1) DEFAULT NULL,
  `incidente_id` bigint(20) unsigned DEFAULT NULL,
  `desconto_continuidade_aplicado` tinyint(1) NOT NULL DEFAULT 0,
  `pricing_snapshot_version` varchar(40) DEFAULT NULL,
  `forma_pagamento_escolhida` varchar(32) DEFAULT NULL,
  `provedor_pagamento_escolhido` varchar(32) DEFAULT NULL,
  `pagamento_destino_admin_id` int(11) DEFAULT NULL,
