  KEY `idx_status` (`status`),
  KEY `idx_criado_em` (`criado_em`),
  KEY `idx_coordenadas_origem` (`lat_origem`,`lng_origem`),
  KEY `idx_expiracao` (`expira_em`),
  KEY `fk_pedidos_veiculo` (`veiculo_id`),
  KEY `idx_pedidos_canal_aquisicao` (`canal_aquisicao`,`criado_em`),
  KEY `fk_pedidos_cidade_atribuicao` (`cidade_id`),
  KEY `idx_pedidos_guincho_id` (`guincho_id`),
  KEY `idx_pedidos_pricing_zone_id` (`pricing_zone_id`),
  KEY `fk_pedidos_service_type` (`service_type_id`),
  KEY `idx_pedido_incidente` (`incidente_id`),
  KEY `idx_pedidos_fatura` (`fatura_id`),
  CONSTRAINT `fk_pedido_incidente` FOREIGN KEY (`incidente_id`) REFERENCES `incidentes` (`id`),
  CONSTRAINT `fk_pedidos_cidade_atribuicao` FOREIGN KEY (`cidade_id`) REFERENCES `cidades` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pedidos_cliente` FOREIGN KEY (`cliente_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pedidos_fatura` FOREIGN KEY (`fatura_id`) REFERENCES `faturas_parceiro` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pedidos_guincho` FOREIGN KEY (`guincho_id`) REFERENCES `guinchos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pedidos_pricing_zone_id` FOREIGN KEY (`pricing_zone_id`) REFERENCES `pricing_zones` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pedidos_service_type` FOREIGN KEY (`service_type_id`) REFERENCES `service_types` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pedidos_veiculo` FOREIGN KEY (`veiculo_id`) REFERENCES `veiculos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pedidos_ibfk_1` FOREIGN KEY (`cliente_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pedidos_ibfk_2` FOREIGN KEY (`veiculo_id`) REFERENCES `veiculos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=200 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
