  CONSTRAINT `fk_atividades_regiao` FOREIGN KEY (`regiao_id`) REFERENCES `prospeccao_regioes` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
