DROP TABLE IF EXISTS `prospeccao_leads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `prospeccao_leads` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `regiao_id` bigint(20) unsigned NOT NULL,
  `place_id` varchar(120) DEFAULT NULL COMMENT 'data_id/data_cid do Google Maps, quando disponivel',
  `nome_negocio` varchar(180) NOT NULL,
  `categoria` varchar(60) NOT NULL,
  `telefone` varchar(30) DEFAULT NULL,
  `telefone_normalizado` varchar(20) DEFAULT NULL COMMENT 'Somente digitos, com DDI, usado para dedupe',
  `endereco` varchar(255) DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `rating` decimal(2,1) DEFAULT NULL,
  `reviews_count` int(10) unsigned DEFAULT NULL,
  `score_go` decimal(6,2) NOT NULL DEFAULT 0.00,
  `fonte` varchar(40) NOT NULL DEFAULT 'serpapi_google_maps',
  `status` enum('novo','na_fila','enviado','respondeu','cadastrado','recusado','invalido') NOT NULL DEFAULT 'novo',
  `criado_em` datetime NOT NULL DEFAULT current_timestamp(),
  `atualizado_em` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lead_regiao_telefone` (`regiao_id`,`telefone_normalizado`),
  KEY `idx_leads_status_score` (`status`,`score_go`),
  KEY `idx_leads_place_id` (`place_id`),
  CONSTRAINT `fk_leads_regiao` FOREIGN KEY (`regiao_id`) REFERENCES `prospeccao_regioes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=341 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

