--
-- Table structure for table `usuarios`
--

DROP TABLE IF EXISTS `usuarios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `usuarios` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nome` varchar(100) NOT NULL,
  `email` varchar(150) NOT NULL,
  `google_subject` varchar(255) DEFAULT NULL,
  `magic_token_hash` char(64) DEFAULT NULL,
  `magic_token_expira_em` datetime DEFAULT NULL,
  `magic_token_canal` enum('whatsapp','email','sms') DEFAULT NULL,
  `senha_hash` varchar(255) DEFAULT NULL,
  `telefone` varchar(20) DEFAULT NULL,
  `telegram_chat_id` varchar(32) DEFAULT NULL,
  `cpf` varchar(14) DEFAULT NULL,
  `tipo` enum('admin','guincho','cliente','funcionario','gerente','especialista','oficina') NOT NULL,
  `perfil_status` varchar(24) NOT NULL DEFAULT 'COMPLETO',
  `perfil_tipo_solicitado` varchar(24) DEFAULT NULL,
