--
-- Table structure for table `veiculos`
--

DROP TABLE IF EXISTS `veiculos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `veiculos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_id` int(11) NOT NULL,
  `placa` varchar(8) NOT NULL,
  `cidade_placa` varchar(100) DEFAULT NULL,
  `uf_placa` varchar(2) DEFAULT NULL,
  `marca` varchar(50) NOT NULL,
  `modelo` varchar(100) NOT NULL,
  `vehicle_brand_id` int(11) DEFAULT NULL,
  `vehicle_model_id` int(11) DEFAULT NULL,
  `ano` int(11) NOT NULL,
  `cor` varchar(30) NOT NULL,
  `tipo` enum('carro','moto','caminhao','van','onibus','outro') NOT NULL,
  `categoria_tarifa` varchar(20) DEFAULT NULL,
  `vehicle_version_id` int(11) DEFAULT NULL,
  `operational_category_id` int(11) DEFAULT NULL,
  `identification_source` varchar(20) DEFAULT 'MANUAL',
  `identification_status` varchar(30) NOT NULL DEFAULT 'PENDING_IDENTIFICATION',
  `identification_confirmed_at` datetime DEFAULT NULL,
  `requires_platform` tinyint(1) DEFAULT NULL,
  `special_restrictions_json` longtext DEFAULT NULL,
  `verification_status` varchar(30) NOT NULL DEFAULT 'DECLARED' COMMENT 'DECLARED | DOCUMENT_SUBMITTED | VERIFIED',
  `vehicle_type` varchar(30) DEFAULT NULL COMMENT 'Ex: automovel_passeio, moto, utilitario, caminhao_leve',
  `fuel_type` varchar(30) DEFAULT NULL COMMENT 'flex, gasolina, etanol, diesel, gnv, eletrico',
  `transmission_type` varchar(30) DEFAULT NULL COMMENT 'manual, automatico',
  `electric_type` varchar(30) DEFAULT NULL COMMENT 'nao_eletrico, hibrido, eletrico_puro',
  `operational_category` varchar(40) DEFAULT NULL COMMENT 'derivada de vehicle_type; usada pela Etapa 15 (compatibilidade prestador x veiculo)',
  `has_spare_tire` tinyint(1) DEFAULT NULL,
  `has_locking_bolt` tinyint(1) DEFAULT NULL,
  `document_uploaded` tinyint(1) NOT NULL DEFAULT 0,
  `document_path` varchar(255) DEFAULT NULL COMMENT 'caminho fora do webroot; nunca expor diretamente',
  `ativo` tinyint(1) DEFAULT 1,
  `criado_em` datetime DEFAULT current_timestamp(),
  `atualizado_em` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_usuario_id` (`usuario_id`),
  KEY `idx_placa` (`placa`),
  KEY `idx_ativo` (`ativo`),
  KEY `fk_veiculos_vehicle_brand` (`vehicle_brand_id`),
  KEY `fk_veiculos_vehicle_model` (`vehicle_model_id`),
  KEY `fk_veiculos_vehicle_version` (`vehicle_version_id`),
  KEY `fk_veiculos_operational_category` (`operational_category_id`),
  CONSTRAINT `fk_veiculos_operational_category` FOREIGN KEY (`operational_category_id`) REFERENCES `vehicle_operational_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_veiculos_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_veiculos_vehicle_brand` FOREIGN KEY (`vehicle_brand_id`) REFERENCES `vehicle_brands` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_veiculos_vehicle_model` FOREIGN KEY (`vehicle_model_id`) REFERENCES `vehicle_models` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_veiculos_vehicle_version` FOREIGN KEY (`vehicle_version_id`) REFERENCES `vehicle_versions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `veiculos_ibfk_1` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=927 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

